// Einmal die Adresse eurer Zeiterfassung eintragen, ohne abschließenden Schrägstrich.
const platformUrl = 'https://DEINE-ZEITERFASSUNG-DOMAIN';
// Optional: bekannte Absenderadresse exakt eintragen. Leer = alle PDFs dieses dedizierten Postfachs.
const allowedSender = '';
return $input.all().map((item, i) => ({json: {...item.json, platform_url: platformUrl.replace(/\/$/, ''), allowed_sender: allowedSender.toLowerCase()}, binary: item.binary, pairedItem: {item: i}}));

const result = [];
for (const [i, item] of $input.all().entries()) {
  const from = item.json.from;
  const sender = (from?.value?.[0]?.address || (typeof from === 'string' ? (from.match(/<([^>]+)>/)?.[1] || from) : '')).trim().toLowerCase();
  if (item.json.allowed_sender && item.json.allowed_sender !== sender) continue;
  for (const file of Object.values(item.binary || {})) {
    if (file.mimeType !== 'application/pdf' && !/\.pdf$/i.test(file.fileName || '')) continue;
    result.push({json: {platform_url: item.json.platform_url, message_id: String(item.json.messageId || item.json.headers?.['message-id'] || item.json.uid || '').slice(0, 500)}, binary: {data: file}, pairedItem: {item: i}});
  }
}
return result;

// Bei nicht lesbaren/gescannten PDFs wird trotzdem das Original übertragen.
// Ohne auswertbaren Text bleibt die Tageszuordnung in der Plattform offen.
const original = $('PDF-Anhaenge').item;
return {json: {platform_url: original.json.platform_url, message_id: original.json.message_id, extracted_text: typeof $json.text === 'string' ? $json.text.slice(0, 1000000) : ''}, binary: original.binary};
